import{_ as t,o as a,i as o,a9 as r}from"./chunks/framework.DuwpaNh0.js";const u=JSON.parse('{"title":"The binary_tree Exception","description":"","frontmatter":{"title":"The binary_tree Exception"},"headers":[],"relativePath":"modules/5-advanced/conductor-interop/4-binary-tree-exception.md","filePath":"modules/5-advanced/conductor-interop/4-binary-tree-exception.md","lastUpdated":1785738413000}'),c={name:"modules/5-advanced/conductor-interop/4-binary-tree-exception.md"};function d(i,e,n,s,l,p){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="the-binary-tree-exception" tabindex="-1">The <code>binary_tree</code> exception <a class="header-anchor" href="#the-binary-tree-exception" aria-label="Permalink to &quot;The `binary_tree` exception&quot;">​</a></h1><p><code>binary_tree</code> is a deliberate, narrow exception to the <a href="./2-pairs-and-arrays.html">&quot;pairs and arrays are the same thing&quot;</a> rule, and worth calling out explicitly so nobody &quot;fixes&quot; it into consistency with everything else by accident:</p><ul><li>It&#39;s small enough to be considered a toy/test module — if it ever needs meaningfully different behavior, it&#39;s easier to just rewrite than to carefully migrate.</li><li>Its <code>is_tree</code>/<code>is_empty_tree</code>/<code>assertNonEmptyTree</code> internals read a tree node&#39;s own <code>DataType</code> tag directly (<code>value.type !== DataType.PAIR</code>) rather than going through a generic helper — this is exactly the kind of hardcoded check the &quot;pairs and arrays are interchangeable&quot; rule says to avoid, and it needed a real code change once py-slang stopped ever producing a <code>PAIR</code> chain for a round-tripped tree value (see <a href="https://github.com/source-academy/modules/pull/813" target="_blank" rel="noreferrer">source-academy/modules#813</a>).</li></ul><p>The actual bug this caused: <code>t = make_tree(1, make_empty_tree(), make_empty_tree())</code> builds a real <code>PAIR</code> structure and hands it back out to Python (converted to a native Python list). Calling <code>entry(t)</code> afterward requires <code>t</code> to convert <em>back</em> into a module value — and once a Python list always becomes a flat <code>DataType.ARRAY</code>, <code>binary_tree</code>&#39;s hardcoded <code>value.type !== DataType.PAIR</code> check rejected it outright, on the very first call after construction, not just on nested trees as originally assumed.</p><p>The fix (<a href="https://github.com/source-academy/modules/pull/813" target="_blank" rel="noreferrer">source-academy/modules#813</a>) accepts <code>DataType.ARRAY</code> as equally valid to <code>DataType.PAIR</code> wherever a tree node&#39;s own tag is checked, without touching <code>make_tree</code>&#39;s own construction (<code>pair_make</code> calls) — only the <em>validation</em> of an incoming, possibly round-tripped value needed to widen.</p><p>If you&#39;re writing a new bundle with tree- or pair-chain-shaped data, prefer going through the generic helpers (<code>pair_head</code>/<code>pair_tail</code>/<code>list_to_vec</code>/etc.) rather than checking <code>.type</code> directly, precisely so you don&#39;t inherit this same fragility.</p>',6)]))}const y=t(c,[["render",d]]);export{u as __pageData,y as default};
